import sys
from collections import deque

MOD = 1000000007
comb = [[0]*100 for _ in range(100)]
stateMap = {}
stateQueue = deque()

class Pair:
    def __init__(self, d, w):
        self.depth = d
        self.ways = w

def main():
    input = sys.stdin.read().strip().split()
    totalN = int(input[0])
    maxK = int(input[1])
    values = list(map(int, input[2:]))

    aCount = 0
    bCount = 0
    for val in values:
        if val == 50:
            aCount += 1
        else:
            bCount += 1

    computeChoose()

    startState = 1000000 + 100 * aCount + bCount
    stateQueue.append(startState)
    stateMap[startState] = Pair(0, 1)

    while stateQueue:
        processState(stateQueue.popleft())

    if 0 in stateMap:
        print(f"{stateMap[0].depth}\n{stateMap[0].ways}")
    else:
        print("-1\n0")

def processState(state):
    side = state // 1000000
    nA = (state % 1000000) // 100
    nB = state % 100

    if side > 0:
        for i in range(nA, -1, -1):
            if 50 * (nA - i) > maxK:
                continue
            for j in range(nB, -1, -1):
                if 50 * (nA - i) + 100 * (nB - j) > maxK:
                    continue
                if i != nA or j != nB:
                    updateState(i, j, side, state, comb[nA][i] * comb[nB][j] % MOD)
    else:
        for i in range(nA, aCount + 1):
            if 50 * (i - nA) > maxK:
                continue
            for j in range(nB, bCount + 1):
                if 50 * (i - nA) + 100 * (j - nB) > maxK:
                    continue
                if i != nA or j != nB:
                    updateState(i, j, side, state, comb[aCount - nA][i - nA] * comb[bCount - nB][j - nB] % MOD)

def updateState(i, j, side, prevState, edgeWays):
    newState = 1000000 * (1 - side) + i * 100 + j
    newDepth = stateMap[prevState].depth + 1
    if newState not in stateMap:
        stateMap[newState] = Pair(newDepth, 0)
        stateQueue.append(newState)
    if stateMap[newState].depth == newDepth:
        stateMap[newState].ways = (stateMap[newState].ways + stateMap[prevState].ways * edgeWays % MOD) % MOD

def computeChoose():
    for i in range(100):
        choose[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i + 1):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

choose = [[0]*100 for _ in range(100)]
aCount = 0
bCount = 0
totalN = 0
maxK = 0

if __name__ == "__main__":
    main()

